from urllib.parse import urlparse
import ipaddress

ALLOWED_HEALTH_HOSTS = set()  # populated from worker_pool on startup

def validate_health_check_url(url: str) -> bool:
    """Validate URL is a known worker health endpoint."""
    parsed = urlparse(url)
    if parsed.scheme not in ('http', 'https'):
        return False
    # Block private/link-local/loopback unless it's a known worker
    try:
        ip = ipaddress.ip_address(parsed.hostname)
        if ip.is_private or ip.is_loopback or ip.is_link_local:
            if parsed.hostname not in ALLOWED_HEALTH_HOSTS:
                return False
    except ValueError:
        # Hostname, not IP - check against allowlist
        if parsed.hostname not in ALLOWED_HEALTH_HOSTS:
            return False
    if parsed.path not in ('/health', '/v1/health', '/metrics'):
        return False
    return True

@router.get('/internal/proxy')
async def proxy_health_check(
    request: Request,
    current_user: User = Depends(get_current_user),
):
    require_role(current_user, Role.OPERATOR)
    target_url = request.query_params.get('url', '')
    if not validate_health_check_url(target_url):
        raise HTTPException(status_code=403, detail='URL not in worker allowlist')
    response = requests.get(target_url, timeout=5, verify=True)
    return JSONResponse(response.json())

