class WorkerLoadTracker:
    KV_REFRESH_INTERVAL_S = 1.0

    def __init__(self, worker_pool, kv_manager):
        self._loads: Dict[str, AtomicCounter] = defaultdict(AtomicCounter)
        self._kv_usage: Dict[str, float] = {}  # Refreshed in background

    async def _kv_refresh_loop(self):
        while True:
            workers = self.worker_pool.get_healthy_workers()
            tasks = [self.kv_manager.get_worker_kv_usage_async(w.id) for w in workers]
            results = await asyncio.gather(*tasks, return_exceptions=True)
            for w, result in zip(workers, results):
                if not isinstance(result, Exception):
                    self._kv_usage[w.id] = result
            await asyncio.sleep(self.KV_REFRESH_INTERVAL_S)

    def select_worker(self, workers, prefix_entry=None):
        """No lock needed — reads are snapshot-consistent."""
        if prefix_entry:
            kv_worker = self.kv_manager.get_block_worker(prefix_entry.kv_block_ids[0])
            if kv_worker and kv_worker.id in {w.id for w in workers}:
                return kv_worker
        return min(workers, key=lambda w: (
            self._loads[w.id].value * 0.7 + self._kv_usage.get(w.id, 0.0) * 0.3
        ))

class RequestScheduler:
    def __init__(self, worker_pool, kv_manager, prefix_store, nixl_bridge):
        self._load_tracker = WorkerLoadTracker(worker_pool, kv_manager)
        self._log_queue: Queue = Queue(maxsize=10000)

    async def schedule_request(self, request, user, priority=1.0):
        prefix_entry = self.prefix_store.lookup(request.token_ids)
        workers = self.worker_pool.get_healthy_workers()
        worker = self._load_tracker.select_worker(workers, prefix_entry)
        await self._load_tracker._loads[worker.id].increment()

        try:
            self._log_queue.put_nowait({
                'timestamp': time.time(), 'request_id': request.id,
                'worker': worker.id, 'input_tokens': len(request.token_ids),
            })
        except asyncio.QueueFull:
            pass  # Drop logs under backpressure

        try:
            if prefix_entry:
                result = await self._dispatch_decode(worker, request, prefix_entry.kv_block_ids)
            else:
                result = await self._dispatch_disaggregated(worker, request)
        finally:
            await self._load_tracker._loads[worker.id].decrement()
        return result

